fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            if keepends {
                // Manually split the string by line boundaries,
                // keeping trailing '\n' or '\r\n' on each line.

                let mut lines = Vec::new();
                let mut start = 0;
                let bytes = s.as_bytes();
                let len = bytes.len();

                for i in 0..len {
                    if bytes[i] == b'\n' {
                        // include up to and including \n
                        let end = i + 1;
                        lines.push(s[start..end].to_string());
                        start = end;
                    } else if bytes[i] == b'\r' {
                        if i + 1 < len && bytes[i + 1] == b'\n' {
                            // Windows-style \r\n line ending, include both
                            let end = i + 2;
                            lines.push(s[start..end].to_string());
                            start = end;
                        } else {
                            // just \r line ending
                            let end = i + 1;
                            lines.push(s[start..end].to_string());
                            start = end;
                        }
                    }
                    // else continue scanning
                }
                // Add remaining text after last line ending if any
                if start < len {
                    lines.push(s[start..].to_string());
                }
                // If string is empty, lines will be empty; add empty string to guarantee non-empty
                if lines.is_empty() {
                    lines.push(String::new());
                }
                lines
            } else {
                // Without keepends, just split by lines, which removes line endings
                // Rust's lines() iterator returns at least one line (empty string if input empty)
                let lines: Vec<String> = s.lines().map(|line| line.to_string()).collect();
                lines
            }
        })
        .collect()
}